const JobCalc=(()=>{const sum=(a,f)=>a.filter(f).reduce((s,r)=>s+(+r.amount||0),0);async function apply(j){if(j.demo)return j;let rs=await JobDB.records(j.id),contract=sum(rs,r=>r.type==='Contract'&&r.state==='signed'),signedChanges=sum(rs,r=>r.type==='Change Order'&&r.state==='signed'),unsignedChanges=sum(rs,r=>r.type==='Change Order'&&r.state!=='signed'),invoiced=sum(rs,r=>r.type==='Customer Invoice'),paid=sum(rs,r=>r.type==='Customer Payment'),trade=sum(rs,r=>['Subcontractor Bill','Supplier Bill'].includes(r.type)&&r.state!=='paid');j.approved=contract+signedChanges;j.invoiced=invoiced;j.paid=paid;j.unsignedChanges=unsignedChanges;j.tradePayables=trade;j.items.contract=contract>0?'ok':'wait';j.items.changes=unsignedChanges>0?'problem':'ok';j.items.invoice=invoiced>0?'ok':'wait';j.items.payment=invoiced>0&&paid>=invoiced?'ok':paid>0?'wait':'wait';j.items.subs=trade>0?'wait':'ok';let insurance=rs.filter(r=>r.type==='Insurance Record');j.items.insurance=!j.insuranceJob||insurance.length?'ok':'wait';j.issues=[];if(!contract)j.issues.push('Signed contract or approved estimate needed');if(unsignedChanges)j.issues.push(money(unsignedChanges)+' in change orders still need approval');if(invoiced>paid)j.issues.push(money(invoiced-paid)+' customer balance remains');if(trade)j.issues.push(money(trade)+' in subcontractor or supplier bills remain unpaid');if(j.insuranceJob&&!insurance.length)j.issues.push('Insurance paperwork still needed');j.status=j.status==='Archived'?'Archived':j.issues.length?'Attention':'Complete';await JobDB.putJob(j);return j}return{apply}})();